ARTICLE_TEXTS = st.builds(
    lambda before, part, after: before + part + after,
    st.text(alphabet=ALPHANUMERIC + SEPARATORS),
    st.sampled_from(ALPHANUMERIC),
    st.text(alphabet=ALPHANUMERIC + SEPARATORS),
)


def test_letters_come_out_in_upper_case() -> None:
    assert normalize_sku("ab12") == "AB12"


@pytest.mark.parametrize("typed", ["ab 12", "ab\t12", "ab-12", "ab_12"])
def test_each_separator_between_two_parts_becomes_a_hyphen(typed: str) -> None:
    assert normalize_sku(typed) == "AB-12"


@pytest.mark.parametrize("typed", ["ab  12", "ab--12", "ab----12", "ab _-\t12"])
def test_run_of_separators_between_two_parts_becomes_one_hyphen(typed: str) -> None:
    assert normalize_sku(typed) == "AB-12"


@pytest.mark.parametrize("typed", [" ab  12 ", "-ab-12", "ab-12_", "\t_ab-12- "])
def test_separators_at_the_ends_are_dropped(typed: str) -> None:
