def test_normalized_article_number_is_its_own_spelling() -> None:
    assert normalize_sku("AB-12") == "AB-12"


@pytest.mark.parametrize("typed", ["", " ", " \t-_", "--"])
def test_text_with_no_letter_and_no_digit_is_rejected(typed: str) -> None:
    with pytest.raises(ValueError, match="no article number"):
        normalize_sku(typed)


