    assert normalize_sku("b2-a1 a1_B2\tc--0").replace("-", "") == "B2A1A1B2C0"


@given(ARTICLE_TEXTS)
def test_I1_normalizing_twice_is_the_same_as_normalizing_once(text: str) -> None:  # noqa: N802
