    with pytest.raises(ValueError, match="no article number"):
        normalize_sku("")


@pytest.mark.parametrize(
    "typed", ["ab 12", " x9--Y8__z7\t", "A-b-C-1-2-3", "q", "__00-0a_A0  ", "1\t2 3-4_5"]
)
def test_seam1_letters_and_digits_keep_their_order_and_number(typed: str) -> None:
    without_separators = typed.upper().translate({ord(sep): None for sep in SEPARATORS})
    assert normalize_sku(typed).replace("-", "") == without_separators


# Separators are drawn as often as letters and digits; the texts are still every text of the
# alphabet, and the one letter or digit in the middle is what the domain asks for.
_CHARS = st.one_of(st.sampled_from(SEPARATORS), st.sampled_from(LETTERS_AND_DIGITS))
_ARTICLE_NUMBERS = st.builds(
    lambda before, part, after: before + part + after,
    st.text(alphabet=_CHARS),
    st.sampled_from(LETTERS_AND_DIGITS),
    st.text(alphabet=_CHARS),
)


@given(_ARTICLE_NUMBERS)
def test_I1_normalizing_twice_is_normalizing_once(typed: str) -> None:
    once = normalize_sku(typed)
    assert normalize_sku(once) == once

